        if(!row){row=document.createElement('div');row.className='timeline-row';row.dataset.eventId=ev.id;row.innerHTML='<b></b><div class="timeline-track"><span class="timeline-bar purple"></span></div>';$('.timeline-row')?.parentElement?.append(row);}
        row.dataset.eventId=ev.id;row.querySelector('b').textContent=ev.assignee||'Unassigned';const bar=$('.timeline-bar',row);bar.textContent=ev.title;bar.dataset.eventId=ev.id;bar.title=`${ev.title} · ${ev.start} to ${ev.due}`;
        const start=Date.parse(`${ev.start}T00:00:00Z`),due=Date.parse(`${ev.due}T00:00:00Z`);const left=Math.max(0,Math.min(6,(start-Date.parse('2026-11-09T00:00:00Z'))/86400000));const right=Math.max(left+1,Math.min(7,(due-Date.parse('2026-11-09T00:00:00Z'))/86400000+1));bar.style.left=`${left/7*100}%`;bar.style.width=`${(right-left)/7*100}%`;
