    const refresh = () => { if (ring) ring.textContent = `${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`; if (label) label.textContent = mode; if (startButton) startButton.textContent = timer ? 'Pause' : 'Start'; };
